  // ═════════════════════════ 署名 / 艺名（全服先到先得）═════════════════════════
  // kind = '导演' / '男优'。opt.reuse = 接着用这个马甲以前注册过的名字（不改当前那个）
  async function claim(kind, name, opt) {
