        a.push('今天 14:00 三号棚那场：尹椿交过来的，女主江蜜' + (jm ? '（片酬 ' + money(jm.fee) + '）' : '') + '，男优位还空着，导演是{{user}}；男优照银星的价目：' + L.actors.map(function (x) { return x.name + ' ' + money(x.fee); }).join('、') + '（开机时从部门预算里付）');
        paid = true;
      }
      var pulled = st.dir.films.filter(function (f) { return f.status === 'pulled'; });
      if (pulled.length) a.push('被审查中心抽查下架、等重剪的：' + pulled.map(function (f) { return '《' + f.title + '》（' + (f.pullWhy || '') + '）'; }).join('、'));
    }
    var pend = st.invites.filter(function (v) { return (v.status === 'pending' || v.status === 'accepted') && Number(v.day) === Number(st.day); });
    if (pend.length) a.push('今天约了：' + pend.map(function (v) { return v.by + '（' + v.where + '）'; }).join('、'));
    news = news || st.news;
    if (news && news.length) a.push('刚才：' + news.map(function (e) { return e.t; }).join('；'));
    if (paid) a.push('钱都由面板结算：正文里有人谈片酬、价钱，就照上面这几个数说，不用另报一个价。');
    return a.join('\n');
  }
  // 导演这一部开机时付掉的：卡司各自的片酬 + 棚租 + 剧组（和 startShootDir 记账的那几笔同一套数）
  function shootFees(st, sh) {
    var sc = parsed(scriptRec(st, sh.scriptId)), out = [];
    var roles = sc ? rolesNeeding(sc) : Object.keys(sh.cast || {}).map(function (k) { return { call: k, side: castByName(st, sh.cast[k]) ? '她' : '他' }; });
    roles.forEach(function (r) {
      var who = (sh.cast || {})[r.call]; if (!who) return;
      if (who === SELF) { out.push('男优位·主是{{user}}自己上（主观镜头），不付男优片酬'); return; }
      if (r.side === '她') { var c = castByName(st, who); out.push(who + ' 片酬 ' + money(Number(c && c.fee) || 0)); }
      else { var a0 = L.actors.find(function (x) { return x.name === who; }); out.push(who + '（男优）片酬 ' + money(a0 ? a0.fee : 0)); }
    });
    out.push('棚租 ' + money(E.studioRent), '剧组 ' + money(E.crew));
    return out;
  }
  function applyRecent(st) {
    st = st || readState();
    try { uninjectPrompts([ID_RECENT]); } catch (e) {}
    if (!identity(st)) return;
    var news = (st.news || []).filter(function (e) { return e && !NEWS_GONE[e.id]; });
    try { injectPrompts([{ id: ID_RECENT, position: 'in_chat', depth: 1, role: 'system', content: recentLine(st, news) + '\n' + TIME_ASK, should_scan: false }]); } catch (e) {}
  }
  function newsReceived() {
    var st = readState(); if (!st.news.length) return;
    var ids = st.news.map(function (e) { return e.id; }); ids.forEach(function (id) { NEWS_GOT[id] = 1; });
    save(function (s) { s.news.forEach(function (e) { if (ids.indexOf(e.id) >= 0) e.got = true; }); });
  }
  function newsSent() {
    var st = readState(), isGot = function (e) { return e && (e.got || NEWS_GOT[e.id]); };
    if (!st.news.some(isGot)) return;
    st.news.forEach(function (e) { if (isGot(e)) NEWS_GONE[e.id] = 1; });
    applyRecent(st);
    save(function (s) { s.news = s.news.filter(function (e) { return !NEWS_GONE[e.id]; }); });
  }

  // 待演的一场（面谈 / 赴约 / 试戏去正文 / 撤片谈话）：同社长室 scene 的规矩——点按钮挂上，正文回了记 got，玩家发下一条才撤
  var GOT_MEM = null;
  function applyScene() {
    try { uninjectPrompts([ID_SCENE]); } catch (e) {}
    var sc = readState().scene;
    if (!sc || !sc.text || !identity()) return;
    try { injectPrompts([{ id: ID_SCENE, position: 'in_chat', depth: 0, role: 'system', content: sc.text, should_scan: true }]); } catch (e) { toast('error', '正文注入失败：' + errMsg(e)); }
  }
  function prefill(text) {
    try {
      var ta = DOC.getElementById('send_textarea');
      if (ta && !String(ta.value || '').trim()) { ta.value = text; try { ta.dispatchEvent(new VIEW.Event('input', { bubbles: true })); } catch (e) {} }
    } catch (e) {}
  }
  async function setScene(kind, name, text, prefillText, toastText) {
    GOT_MEM = null;
    await save(function (s) { s.scene = { kind: kind, name: name, text: text, at: Date.now(), got: false }; });
    applyScene(); if (prefillText) prefill(prefillText);
    closePanel(); toast('success', toastText);
  }
  async function clearScene() { try { uninjectPrompts([ID_SCENE]); } catch (e) {} GOT_MEM = null; await save(function (s) { delete s.scene; }); }

  // 片场：拍摄中每轮都挂当前这一场（剧本系统第三节：片头 + 选角 + 前情 + 上一场的钩 + 状态 + 当前这一场全文）
  var SCRIPT_CACHE = {};
  function libScript(id) { return (C.GRID.library || []).find(function (x) { return x.id === id; }) || null; }
  function scriptRec(st, id) {
    if (!id) return null;
    var lb = libScript(id); if (lb) return { id: lb.id, raw: lb.text, source: 'lib', onlyActor: lb.onlyActor, slots: lb.slots };
    return st.dir.scripts.concat(st.act.scripts).find(function (x) { return x.id === id; }) || null;
  }
  function parsed(rec) {
    if (!rec) return null;
    var key = rec.id + ':' + String(rec.raw || '').length;
    if (!SCRIPT_CACHE[key]) {
      if (Object.keys(SCRIPT_CACHE).length > 80) SCRIPT_CACHE = {};
      var p = C.parseScript(rec.raw); if (p.ok && !p.tier) p.tier = rec.tier || 'R18 常见XP';
      SCRIPT_CACHE[key] = p.ok ? p : null;
    }
    return SCRIPT_CACHE[key];
  }
  function curShoot(st) { var id = identity(st); return id === '导演' ? st.dir.shoot : id === '男优' ? st.act.shoot : null; }
  function applyShoot(st) {
    st = st || readState();
    try { uninjectPrompts([ID_SHOOT]); } catch (e) {}
    var sh = curShoot(st); if (!sh) return;
    var sc = parsed(scriptRec(st, sh.scriptId)); if (!sc) return;
    var text = C.shootPrompt(sc, sh, identity(st));
    if (sh.paused) text = '【片场 · 暂停】刚才有人喊了「大头菜」。这一条立刻停：演员停手，摄影停机，导演喊卡开灯，全组先问人再说别的。这一轮只写停下来以后的事，不接着拍。\n' + text;
    try { injectPrompts([{ id: ID_SHOOT, position: 'in_chat', depth: 0, role: 'system', content: text, should_scan: true }]); } catch (e) {}
  }

  // ═════════════════════════ 过日子 ═════════════════════════
  // 日子两条路往前走：面板里「结束今天 / 跳到下一件事」，或者正文过了夜（[TIME] 的日期往后跳）
  function todayGigs(st) { return st.act.offers.filter(function (g) { return Number(g.day) === Number(st.day); }); }
  function castByName(st, nm) { return st.dir.cast.find(function (c) { return c.stageName === nm || c.realName === nm; }) || null; }
  // 剪完就上架（v0.1.5 起不送审、不等）；relist = 被抽查下架、重剪以后重新上架（首周只剩三成：老客人已经看过一遍了）
  function releaseFilm(s, f, out, relist) {
    f.status = 'released'; f.releaseDay = s.day; f.checkFrom = s.day; f.checked = 0; delete f.pullWhy;
    var cp = Math.round(C.monthCopies(f.score, 0, f.tier) * (relist ? 0.15 : 0.5));
    f.sales = (f.sales || 0) + cp; f.monthCopies = (relist ? Number(f.monthCopies) || 0 : 0) + cp;
    addLedger(s, 'sale', cp * E.salePrice, (relist ? '重新上架：《' : '市场首发：《') + f.title + '》首周 ' + cp + ' 份');
    addNews(s, '《' + f.title + '》今天' + (relist ? '重剪完重新' : '在市场') + '上架');
    out.push('📀《' + f.title + '》今天' + (relist ? '重新' : '在市场') + '上架，首周卖了 ' + cp + ' 份（' + money(cp * E.salePrice) + '）');
    if (!relist && C.rndFloat() < 0.3) { var fl = C.pick(C.afterMishaps().filter(function (x) { return !/撤|审/.test(x); })); if (fl) { addNews(s, '《' + f.title + '》上架当天：' + fl); out.push('📀 上架当天：' + fl); } }
  }
  // 审查中心抽查（上架后头一个月，每天掷一次；一部片一个窗口只抽一次）。force：测试 / 调试用，'pass' | 'fail'
  var PULLED_Q = [];   // 这次存档里被下架的片子：存完以后让联机那份也跟着下架（afterSave 里清）
  function spotCheck(s, f, out, force) {
    if (!force && C.rndFloat() >= C.checkDrawP(f)) return false;
    f.checked = s.day;
    var bad = force === 'fail' || (force !== 'pass' && C.rndFloat() < C.checkFailP(f));
    if (!bad) {
      f.checkOk = s.day;
      addNews(s, '审查中心的方正抽查了《' + f.title + '》，一帧一帧看完，盖了章');
      out.push('🔎 方正抽查了《' + f.title + '》：没挑出毛病');
      return true;
    }
    var why = C.pick(L.checkWhy || []) || '打码薄了一帧';
    f.status = 'pulled'; f.pullWhy = why; f.pulledDay = s.day; f.monthCopies = 0;
    addEvent(s, { kind: 'check', filmId: f.id, title: f.title, why: why, text: '审查中心的方正抽查了《' + f.title + '》：' + why + '。片子已经下架，重剪（' + money(E.reEdit) + '）以后才能重新上架，下架这几天没有销量。' });
    addNews(s, '审查中心的方正抽查《' + f.title + '》，挑出毛病：' + why + '。片子下架了，等重剪');
    out.push('⚠ 方正抽查《' + f.title + '》：' + why + '。已经下架，去「市场」重剪');
    ddEvent('takedown', { text: '方正抽查《' + f.title + '》：' + why + '，下架等重剪', key: 'check:' + f.id + ':' + s.day });
    PULLED_Q.push(f.id);
    return true;
  }
  function monthly(s, out) {
    var id = identity(s), d = s.day;
    if (id === '导演') {
      addLedger(s, 'grant', E.dirMonthlyGrant, '戴晶拨下这个月的部门预算');
      addLedger(s, 'cost', -E.dirMonthlyCost, '这个月的剪辑室、人工和器材');
      var tot = 0, lines = [];
      s.dir.films.forEach(function (f) {
        if (f.status !== 'released') { f.monthCopies = 0; return; }
        var age = C.monthKey(d) - C.monthKey(f.releaseDay);
        var cp = C.monthCopies(f.score, age, f.tier); f.sales = (f.sales || 0) + cp; f.monthCopies = cp; tot += cp * E.salePrice;
        if (cp) lines.push('《' + f.title + '》' + cp + ' 份');
      });
      if (tot) { addLedger(s, 'sale', tot, '市场上个月的回款：' + lines.join('、')); out.push('市场回款 ' + money(tot)); }
      // 招聘通知上写的：月榜进前十，社长请吃牛排
      if (!s.seed) s.seed = (C.rndU32() % 2147483646) + 1;
      var top = C.marketBoard(s.seed, d, s.dir.films.filter(function (f) { return f.status === 'released'; })).filter(function (r) { return r.ours && r.rank <= 10; })[0];
      if (top) {
        addNews(s, '《' + top.title + '》进了市场月榜第 ' + top.rank + ' 名');
        out.push('🏆《' + top.title + '》进了市场月榜第 ' + top.rank + ' 名，戴晶说请吃牛排');
        ddEvent('rank', { text: '《' + top.title + '》进了月榜第 ' + top.rank + ' 名', key: 'rank:' + d + ':' + (top.id || top.title) });
        var v = { id: C.uid('v'), by: '戴晶', day: d, recvDay: d, status: 'pending', where: '牛排馆', text: '戴晶：《' + top.title + '》月榜第 ' + top.rank + '。说话算话，今晚牛排，我请。', scene: '戴晶在牛排馆请{{user}}吃饭，庆祝《' + top.title + '》进了市场月榜前十；吃到一半，她从包里掏出一份新企划。' };
        s.invites.push(v); if (DD) try { DD.pushInvite(s, v); } catch (e) {}
      }
      out.push('月初：戴晶拨款 ' + money(E.dirMonthlyGrant) + '，部门开支 ' + money(-E.dirMonthlyCost));
    } else if (id === '男优') {
      addLedger(s, 'rent', -E.rent, '这个月的房租');
      out.push('月初：交房租 ' + money(E.rent));
    }
  }
  function rollDay(s, out, quiet) {
    s.day++; s.clock = '09:00';
    var id = identity(s), d = s.day;
    if (C.isFirst(d)) monthly(s, out);
    if (id === '导演') {
      if (s.dir.plan0 && s.dir.plan0.day < d) delete s.dir.plan0;   // 开场那场过了当天就不再提
      s.dir.stamina = Math.min(100, (Number(s.dir.stamina) || 0) + 60);
      s.dir.cast.forEach(function (c) { if (C.canShootDay(c) === d && !NPC_CAST[c.id]) out.push('📋 ' + c.stageName + ' 今天起可以进棚了'); });
      s.dir.films.forEach(function (f) { if (f.status === 'released' && !f.checked && f.checkFrom != null && d > f.checkFrom && d <= C.checkEnd(f)) spotCheck(s, f, out); });
    }
    if (id === '男优') {
      var A = s.act;
      A.stamina = Math.min(100, (Number(A.stamina) || 0) + 60);
      if (d - (Number(A.doseDay) || 1) >= 7 && A.dose > 0) { A.dose--; A.doseDay = d; }
      A.transit = A.transit.filter(function (t) { if (t.day <= d) { addLedger(s, 'pay', t.amount, t.note + '（到账）'); out.push('💴 到账 ' + money(t.amount) + '：' + t.note); return false; } return true; });
      A.offers.forEach(function (g) {
        if (g.status === 'accepted' && g.day < d && !(A.shoot && A.shoot.gigId === g.id)) { g.status = 'missed'; A.fame = Math.max(0, A.fame - 3); out.push('✗ 错过了 ' + C.mdShort(g.day) + ' ' + g.studio + ' 的通告，名气 -3'); }
        if (g.status === 'open' && g.day < d) g.status = 'expired';
      });
      A.offers = A.offers.filter(function (g) { var old = d - g.day; return !((g.status === 'expired' || g.status === 'declined') && old > 3) && !(/^(done|missed|cancelled|dropped)$/.test(g.status) && old > 30); });
      if (A.checkupUntil === d) out.push('🩺 体检报告今天到期，去钱包续一下，不然接不了戏');
      if (A.restUntil && A.restUntil === d) out.push('身体缓过来了，可以接戏了');
      if (A.guarantee && C.dateOf(d).getDay() === 1) guaranteeGigs(s, out);
      var fresh = quiet && C.rndFloat() < 0.6 ? [] : drawOffers(s, 1 + (C.rndFloat() < 0.5 ? 1 : 0));
      if (fresh.length && !quiet) out.push('📨 新片约 ' + fresh.length + ' 个');
    }
    s.invites.forEach(function (v) { if ((v.status === 'pending' || v.status === 'accepted') && v.day < d) v.status = v.status === 'pending' ? 'missed' : 'went'; });
    s.invites = s.invites.filter(function (v) { return d - v.day < 30; });
    if (!quiet) drawInvites(s);   // 一口气跳好几天：中间那几天不约人，免得叮叮一下子涌进一堆
    return out;
  }
  // 下一件值得跳到的日子（新人能进棚、通告、到账、月初）
  function nextMark(st) {
    var d = st.day, cands = [], id = identity(st);
    var dt = C.dateOf(d); cands.push(C.dayOfDate(new Date(dt.getFullYear(), dt.getMonth() + 1, 1)));
    if (id === '导演') {
      st.dir.cast.forEach(function (c) { var k = C.canShootDay(c); if (k > d) cands.push(k); });
    } else {
      st.act.offers.forEach(function (g) { if (g.status === 'accepted' && g.day > d) cands.push(g.day); });
      st.act.transit.forEach(function (t) { if (t.day > d) cands.push(t.day); });
    }
    st.invites.forEach(function (v) { if (v.status === 'accepted' && v.day > d) cands.push(v.day); });
    return Math.min.apply(null, cands);
  }
  function markText(st, day) {
    var a = [], id = identity(st);
    if (day > 1 && C.isFirst(day)) a.push('月初结账');
    if (id === '导演') {
      st.dir.cast.forEach(function (c) { if (C.canShootDay(c) === day) a.push(c.stageName + ' 可以进棚'); });
    } else {
      st.act.offers.forEach(function (g) { if (g.status === 'accepted' && g.day === day) a.push(g.time + ' ' + g.studio + ' 的通告'); });
      st.act.transit.forEach(function (t) { if (t.day === day) a.push('片酬到账'); });
    }
    st.invites.forEach(function (v) { if (v.status === 'accepted' && v.day === day) a.push(v.by + ' 的约'); });
    return a.join('、');
  }
  function rollToasts(out) {
    if (!out.length) return;
    out.slice(0, 6).forEach(function (t, i) { setTimeout(function () { toast(/⚠|✗/.test(t) ? 'warning' : 'info', t); }, i * 300); });
    if (out.length > 6) toast('info', '……还有 ' + (out.length - 6) + ' 件，看日历');
  }
  async function endDays(n) {
    var out = [];
    await save(function (s) {
      var done = 0;
      for (var i = 0; i < n; i++) {
        rollDay(s, out, i < n - 1); done++;
        // 半路排进来的通告（保底合同每周一自动排）落在今天：停下，别一口气跳过去记成错过
        if (i < n - 1 && identity(s) === '男优' && s.act.offers.some(function (g) { return g.status === 'accepted' && g.day === s.day; })) { drawInvites(s); out.push('⏸ 停在 ' + C.mdText(s.day) + '：今天有通告'); break; }
      }
      if (done > 1) addNews(s, '一晃过了 ' + done + ' 天');
    });
    rollToasts(out); render(); ddBadge();
  }

  // ── 日历上的邀约（纯代码，不花 token）──
  var INV_CAP = 60;
  function drawInvites(s) {
    var id = identity(s); if (!id) return [];
    if (s.invDone >= s.day) return [];
    s.invDone = s.day;
    var pool = (L.invites || []).filter(function (t) { return !t.face || t.face === id; }), out = [];
    var n = C.rndFloat() < 0.55 ? 1 : (C.rndFloat() < 0.3 ? 2 : 0);
    C.drawN(pool, n).forEach(function (t) {
      var ahead = C.rndFloat() < 0.6 ? 0 : 1 + C.randInt(2);
      var v = { id: C.uid('v'), by: t.who, day: s.day + ahead, recvDay: s.day, status: 'pending', text: t.text, where: t.where, scene: t.scene };
      s.invites.push(v); out.push(v);
      if (DD) try { DD.pushInvite(s, v); } catch (e) {}
    });
    if (s.invites.length > INV_CAP) s.invites = s.invites.slice(-INV_CAP);
    return out;
  }
  var PING_SKIP = { swipe: 1, regenerate: 1, 'continue': 1, impersonate: 1, quiet: 1, first_message: 1 };
  function maybePing(type) {
    if (PING_SKIP[type]) return;
    var st = readState(), P = L.pings || {};
    if (!identity(st) || curShoot(st)) return;   // 拍摄中不打扰
    var pend = st.invites.filter(function (v) { return v.status === 'pending' && Number(v.day) === Number(st.day); }).length;
    var due = (Number(st.pingGap) || 0) + 1 >= (Number(P.gap) || 3) && pend < (Number(P.maxPending) || 2) && C.rndFloat() < (P.chance == null ? 0.3 : P.chance);
    var got = null;
    save(function (s) {
      if (due) { s.invDone = 0; var a = drawInvites(s); got = a[0] || null; s.pingGap = 0; }
      else s.pingGap = (Number(s.pingGap) || 0) + 1;
    }).then(function () { if (got) { toast('info', '📅 ' + got.text + '（叮叮）'); ddBadge(); } });
  }
  function inviteSceneText(v, st) {
    var id = identity(st);
    return '【片场 · 赴约】' + C.mdText(st.day) + '，{{user}}（' + (id === '导演' ? '银星的导演' : '银星的男优') + '）去了' + v.where + '：' + v.by + '约的。' + (v.scene || '') + '\n这一段正文让' + v.by + '当主角；一场里有名有姓的人不超过三个。{{user}} 的话和决定留给 {{user}}。';
  }
  async function goInvite(id) {
    var st = readState(), v = st.invites.find(function (x) { return x.id === id; });
    if (!v) return;
    await save(function (s) { var x = s.invites.find(function (y) { return y.id === id; }); if (x) x.status = 'went'; addNews(s, '去' + v.where + '赴' + v.by + '的约'); });
