      catch (e) { last = errMsg(e); if (is429(e)) break; continue; }
      var r = C.parseScene(raw, n);
      if (r.ok) {
        var bak = clone(sc.scenes);
        if (C.mergeScene(sc, r.scene) && C.scriptSane(sc)) return true;
