        s.dir.shoot = null;
        addNews(s, '《' + sh.title + '》杀青，NG ' + sh.ng + ' 次，进剪辑室');
        out.push('🎬 杀青！《' + sh.title + '》进剪辑室，剪好了在「市场」点上架');
      } else {
        var A = s.act, g = A.offers.find(function (x) { return x.id === sh.gigId; }) || {};
        var fin = Object.keys(sh.finishes), fakes = fin.filter(function (k) { return sh.finishes[k] === 'fake'; }).length, oks = fin.length - fakes;
        var pay = Math.round((Number(g.pay) || E.gigBase) * Math.pow(0.7, fakes) / 10) * 10;
        A.transit.push({ day: s.day + E.payDelay, amount: pay, note: (g.studio || '片商') + '《' + sh.title + '》的片酬' });
        var okAll = fakes === 0;
        A.streak = okAll ? (A.streak || 0) + 1 : 0;
        A.fame = Math.max(0, (A.fame || 0) + (okAll ? 3 : -2) + (g.named ? 1 : 0));
        if (g.named) A.named = (A.named || 0) + 1;
        A.films.unshift({ id: C.uid('af'), title: sh.title, studio: g.studio || '', costar: g.costar || '', day: s.day, tier: sh.tier, pay: pay, okAll: okAll, ng: sh.ng, finishes: oks + '/' + fin.length });
        if (ON) ON.queueActor(s, A.films[0].id);   // 联机男优榜：排进待记，存完马上去记（连不上 / 太近 = 下次打开面板补）
        if (g.id) g.status = 'done';
        A.shoot = null;
        if (!A.guarantee && A.streak >= E.guaranteeAfter && g.studioId && g.studioId !== 'creator') {
          A.guarantee = { studio: g.studio, studioId: g.studioId, perWeek: 2, since: s.day };
          out.push('📋 ' + g.studio + ' 来谈保底合同：每周两场，片酬打九折换稳定（每周一自动排进通告）');
          addNews(s, g.studio + '给了保底合同：每周两场');
        }
        addNews(s, '《' + sh.title + '》杀青' + (okAll ? '，一条条都收住了' : '，有 ' + fakes + ' 场是特写糊弄过去的'));
        out.push('🎬 杀青！片酬 ' + money(pay) + ' 进在途，' + C.mdShort(s.day + E.payDelay) + ' 到账。名气 ' + (okAll ? '+3' : '-2'));
      }
    });
    UI.modal = null; applyShoot(); rollToasts(out); render();
    if (fk === 'act' && ON) ON.flushPending();
