  // 剪好了 → 直接上架（v0.1.5：不送审、不等；上架后头一个月审查中心会抽查，见 spotCheck）
  async function publishFilm(fid) {
    var out = [];
    await save(function (s) { var x = s.dir.films.find(function (y) { return y.id === fid; }); if (x && x.status === 'edit') releaseFilm(s, x, out); });
    rollToasts(out); render();
  }
  // 被抽查下架的：花钱重剪，重新上架（抽查期重新算一个月，重剪过的毛病少一截）
  async function reEdit(fid) {
    var st = readState(), f0 = st.dir.films.find(function (x) { return x.id === fid; }); if (!f0 || f0.status !== 'pulled') return;
    if (st.money < E.reEdit) { toast('warning', '部门预算不够重剪（要 ' + money(E.reEdit) + '）'); return; }
    var out = [];
    await save(function (s) {
      var x = s.dir.films.find(function (y) { return y.id === fid; }); if (!x || x.status !== 'pulled') return;
      x.reEdits = (x.reEdits || 0) + 1; addLedger(s, 'reedit', -E.reEdit, '《' + x.title + '》重剪、重新打码');
      s.events.forEach(function (e) { if (e.kind === 'check' && e.filmId === fid && e.status === 'open') e.status = 'done'; });
      releaseFilm(s, x, out, true);
    });
    rollToasts(out); render();
  }
  // 日历上的事件：抽查下架（kind 'check'）。talk = 去审查中心听方正说（挂一场正文）；ok = 知道了；fix = 去市场重剪
  function checkSceneText(ev, st) {
    return '【片场 · 抽查】审查中心的方正把{{user}}叫到审查中心的小屋：《' + (ev.title || '') + '》上架以后被抽查，挑出来的毛病是「' + (ev.why || '') + '」，片子已经下架。这一段正文让方正当主角：他把那一段一帧一帧放给{{user}}看，说清楚哪里不行、重剪要改什么；红包他不收，口也不松。{{user}} 的话和决定留给 {{user}}。';
  }
  async function eventAct(eid, a) {
    var st = readState(), ev = st.events.find(function (x) { return x.id === eid; }); if (!ev) return;
    if (a === 'talk' && ev.kind === 'check') { await setScene('check', '方正', checkSceneText(ev, st), '（去审查中心找方正）', '方正在审查中心等你，去正文吧'); return; }
    if (a === 'fix') { UI.tab = 'market'; lsSet(TAB_KEY, UI.tab); if (ON) { try { ON.M.ui.view = 'mine'; } catch (e) {} } render(); return; }
    await save(function (s) { var x = s.events.find(function (y) { return y.id === eid; }); if (x) x.status = 'done'; });
    render();
  }

  // ═════════════════════════ 自己写剧本 ═════════════════════════
  async function saveCustom(text) {
    var r = C.parseScript(text);
    if (!r.ok) { UI.modal.err = '没认出来：' + r.why + '。格式照剧本库那几部：企划/档位/卖点/角色……一行 ---，然后 #1 场名｜地点、在场、情、新、要。'; render(); return; }
    if (!r.roles.some(function (x) { return x.side === '她'; })) { UI.modal.err = '「角色」一行里至少要有一个「她＝名字（年龄，身份）」：开机选角、片酬都看这一行。'; render(); return; }
    if (!r.tier) { UI.modal.err = '「档位」一行没认出来：写 全年龄 / R15 / R18常见XP / R18 BDSM / 深渊 里的一个。'; render(); return; }
    var st = readState(), fk = faceKey(st);
    var rec = { id: C.uid('s'), title: r.title, tier: r.tier, lineup: r.lineup, raw: C.scriptAllText(r), source: 'mine', day: st.day };
    await save(function (s) { s[fk].scripts.unshift(rec); if (s[fk].scripts.length > 30) s[fk].scripts = s[fk].scripts.slice(0, 30); });
    UI.modal = null; toast('success', '存进「我写的」：《' + r.title + '》'); render();
  }

